def environment(c):
 e=os.environ.copy();e['LEADGEN_METADATA_RUN_ROOT']=str(P);e['DATABASE_URL']=read(H/'.credentials/zenithjoy-db.json')['DATABASE_URL'];e['LEADGEN_FEISHU_CREDENTIALS']=str(H/'.credentials/leadgen-feishu-yuesheng-live.json');e['LEADGEN_SCORE_AUDIT_DIR']=str(P/'model-score-audit')
 for f in ['cecelia-internal.env','openrouter.env','dashscope.env']:e.update(envfile(H/'.credentials'/f))
 cos=read(H/'.credentials/cos-delivery-source-20261117.json');e['COS_SECRET_ID']=cos['TENCENT_VPS_SECRET_ID'];e['COS_SECRET_KEY']=cos['TENCENT_VPS_SECRET_KEY']
 return e

def qualification_recovery_guard(c,key,kind,args):
 path=P/'qualification-artifacts.py';raw=path.read_bytes()
 if path.is_symlink() or hashlib.sha256(raw).hexdigest()!=c['verification']['qualification_sha256']['qualification-artifacts.py']:raise ValueError('QUALIFICATION_GUARD_SOURCE_CHANGED')
 module={'__name__':'qualification_recovery_guard','__file__':str(path)}
 exec(compile(raw,str(path),'exec'),module)
 module['assert_recovery_action'](c,key,kind,args)

def invoke(c,key,kind,args):
 qualification_recovery_guard(c,key,kind,args)
 if kind in {'outreach','outreach-phone','outreach-proof'}:
  from outreach104.tool_extension import invoke as invoke104
  return invoke104(P,c,key,kind,args,{'environment':environment,'task_authority':task_authority,'resource_authority':resource_authority,'ssh':ssh})
 if kind=='collection-evidence':
  if key!='collection' or c['assigned_workflow']!='102' or len(args)!=1:raise ValueError('COLLECTION_EVIDENCE_SCOPE')
  resource_authority(c)
  return subprocess.run([c['node'],str(P/'collection-evidence/main.mjs')],input=args[0],capture_output=True,text=True,env=environment(c),timeout=90)
 if kind=='collection-readback':
  if key!='collection' or c['assigned_workflow']!='102' or args:raise ValueError('COLLECTION_READBACK_SCOPE')
  resource_authority(c)
  return subprocess.run([c['node'],str(P/'collection-readback.mjs')],input=json.dumps(c),capture_output=True,text=True,env=environment(c),timeout=90)
 if kind=='native-readback':
  if args:raise ValueError('NATIVE_READBACK_TAKES_NO_ARGS')
  return subprocess.run([c['node'],str(P/'native-inspect.mjs')],input=json.dumps(c),capture_output=True,text=True,timeout=45)
 if kind=='phone':
  approved=phone_args(c,key,args);cmd=args[0]
  if key=='qualification' and cmd in {'swipe-evidence','record-start'}:
   history=[read(f).get('binding',{}) for f in (P/'receipts').glob('*.json')]
   if sum(b.get('activity')==key and b.get('kind')=='phone' and b.get('args',[None])[0]==cmd for b in history)>1:raise ValueError('SINGLE_CAPTURE_OR_SEEK_LIMIT')
  if cmd not in READ and cmd not in {'lock-acquire','lock-acquire-new'}:resource_authority(c)
  elif cmd in {'lock-acquire','lock-acquire-new'}:
   x=central(c)
   if x['locked_by']!=c['central_owner']:raise ValueError('CENTRAL_OWNER_REQUIRED')
  return subprocess.run(ssh(c,approved),capture_output=True,text=True,timeout=420)
 if kind=='brain':
  route=args[0];body=json.loads(args[1]) if len(args)>1 else None
  if body is not None:
   allowed=(key=='preflight' and route=='device-locks/acquire') or (key=='cleanup' and route=='device-locks/release')
   if not allowed or body.get('device_name')!=c['serial'] or body.get('locked_by')!=c['central_owner']:raise PreDispatchRejected()
   if route.endswith('release'):
    x=central(c)
    if body.get('expected_lease_version')!=x['lease_version']:raise ValueError('LEASE_CAS_REQUIRED')
  elif route!='device-locks':raise ValueError('BRAIN_READ_SCOPE')
  return {'exit_code':0,'data':brain(route,body)}
 if kind=='business':
  i=scoped_business(c,key,json.loads(args[0]))
  if c['assigned_workflow'] in ['101','102']:resource_authority(c)
  return subprocess.run([c['node'],str(P/'business.mjs')],input=json.dumps(i),capture_output=True,text=True,env=environment(c),timeout=420)
 if kind=='metrics':
  if key!='collect_videos':raise ValueError('METRICS_ACTIVITY_SCOPE')
  return subprocess.run([c['node'],str(P/'metrics.mjs')],input=args[0],capture_output=True,text=True,env=environment(c),timeout=20)
 if kind=='qualify':
  if key!='qualification' or len(args)!=2 or args[0] not in c['verification']['102']['video_ids']:raise ValueError('QUALIFICATION_SCOPE')
  resource_authority(c);audio=pathlib.Path(args[1]).resolve()
  if not audio.is_relative_to(P/'native'):raise ValueError('AUDIO_SOURCE_SCOPE')
  return subprocess.run([c['node'],str(P/'qualification/main.mjs')],input=json.dumps({'context':c,'video_id':args[0],'audio':str(audio),'artifact_dir':str(P/'qualification-receipts'/args[0])}),capture_output=True,text=True,env=environment(c),timeout=420)
 if kind=='fetch-native':
  name=args[0];run=c['tasks'][c['assigned_workflow']]['run_tag']
  if not re.fullmatch(re.escape(run)+r'-[A-Za-z0-9_.-]+',name) and not (c['assigned_workflow']=='104' and name==c['local_owner']+'-outward-ledger.jsonl'):raise ValueError('NATIVE_FILE_SCOPE')
  target=P/'native'/name;target.parent.mkdir(exist_ok=True)
  remote=c['native_root']+'/'+name
  incomplete=P/'download-incomplete';incomplete.mkdir(exist_ok=True)
  partial=incomplete/(target.name+'.download-part')
  remaining=(c['cleanup_deadline_ms'] if key=='cleanup' else c['business_deadline_ms'])/1000-time.time()
  transfer_timeout=max(1,min(600 if target.suffix.lower() in {'.mkv','.mp4','.wav'} else 120,remaining))
  if c.get('transport')=='local':
   pinned_transport(c);source=pathlib.Path(remote);source_root=pathlib.Path(c['native_root']).resolve()
   if source.is_symlink() or not source.is_file() or source.resolve().parent!=source_root:raise ValueError('NATIVE_LOCAL_SOURCE')
   before=source.stat();shutil.copy2(source,partial);after=source.stat()
   if (before.st_ino,before.st_size,before.st_mtime_ns)!=(after.st_ino,after.st_size,after.st_mtime_ns):raise ValueError('NATIVE_LOCAL_SOURCE_CHANGED')
  else:
   r=subprocess.run(['scp','-p','-o','BatchMode=yes','-o','ControlMaster=no','-o','ControlPath=none','-o','ConnectTimeout=12','-o','ServerAliveInterval=15','-o','ServerAliveCountMax=3','-o','ProxyJump='+c['ssh_jump'],c['host']+':'+remote,str(partial)],capture_output=True,text=True,timeout=transfer_timeout)
   if r.returncode:return r
  os.replace(partial,target)
  return {'exit_code':0,'data':{'path':str(target),'sha256':hashlib.sha256(target.read_bytes()).hexdigest(),'mtime':target.stat().st_mtime,'remote_name':name}}
 if kind=='proof':
  if key not in ['collect_videos','qualification']:raise ValueError('PROOF_ACTIVITY_SCOPE')
  proposed=json.loads(args[0]);dest=pathlib.Path(c['verification']['proof_manifest_path']);m=read(dest)
  allowed='filter_evidence' if key=='collect_videos' else 'qualification_evidence'
  if set(proposed)!={allowed}:raise ValueError('PROOF_FIELDS')
  def check_refs(x):
   if isinstance(x,dict):
    if 'path' in x:
     p=pathlib.Path(x['path']);r=p.resolve()
     roots=[P/'native',P/'qualification-receipts',P/'receipts',P/'phone-cli-source.zsh']
     if p.is_symlink() or not any(r==v.resolve() or r.is_relative_to(v.resolve()) for v in roots) or hashlib.sha256(p.read_bytes()).hexdigest()!=x.get('sha256'):raise ValueError('RAW_PROOF_REFERENCE')
    for v in x.values():check_refs(v)
   if isinstance(x,list):
    for v in x:check_refs(v)
  check_refs(proposed);m.update(proposed);atomic(dest,m);return {'exit_code':0,'data':{'proof_manifest':str(dest),'supplied_raw_references':True,'acceptance_not_asserted':True}}
 raise ValueError('TOOL_KIND')

